import binascii, struct, sys, os

def crc32(b): return binascii.crc32(b) & 0xffffffff

def vli(n):
    out=bytearray()
    while n >= 0x80:
        out.append((n & 0x7f)|0x80); n >>= 7
    out.append(n)
    return bytes(out)

CHECK_SIZE = {0:0,1:4,2:4,3:4,4:8,5:8,6:8,7:16,8:16,9:16,10:32,11:32,12:32,13:64,14:64,15:64}

def stream_header(check):
    flags = bytes([0x00, check])
    return b"\xfd7zXZ\x00" + flags + struct.pack("<I", crc32(flags))

def stream_footer(check, backward_size_bytes):
    # backward_size field value = real/4 - 1
    bs = struct.pack("<I", backward_size_bytes//4 - 1)
    flags = bytes([0x00, check])
    body = bs + flags
    return struct.pack("<I", crc32(body)) + body + b"YZ"

def block_header(filters, comp_size=None, uncomp_size=None):
    # filters: list of (id, propbytes)
    flags = len(filters)-1
    body = bytearray()
    if comp_size is not None: flags |= 0x40
    if uncomp_size is not None: flags |= 0x80
    body.append(flags)
    if comp_size is not None: body += vli(comp_size)
    if uncomp_size is not None: body += vli(uncomp_size)
    for fid, props in filters:
        body += vli(fid) + vli(len(props)) + props
    # header size = multiple of 4, includes size byte + body + padding + crc32
    n = 1 + len(body) + 4
    total = (n + 3) // 4 * 4
    pad = total - n
    hdr = bytes([total//4 - 1]) + bytes(body) + b"\x00"*pad
    return hdr + struct.pack("<I", crc32(hdr))

def index(records):
    # records: list of (unpadded_size, uncompressed_size)
    body = bytearray(b"\x00")
    body += vli(len(records))
    for u,c in records:
        body += vli(u) + vli(c)
    while len(body) % 4 != 0:
        body += b"\x00"
    return bytes(body) + struct.pack("<I", crc32(bytes(body)))

def pad4(n): return (4 - n % 4) % 4
EOF
